question.answer:
from dataclasses import dataclass from enum import Enum
# ---------------------------------------------------------------------- # Supplied. Do not change anything in this block. # ---------------------------------------------------------------------- class Status(Enum): OK = "OK" FAILED = "FAILED" STALE = "STALE"
@dataclass(frozen=True) class Reading: sensor: str value: float
@dataclass(frozen=True) class Alarm: code: str status: Status
@dataclass(frozen=True) class Heartbeat: node: str # ---------------------------------------------------------------------- # End of the supplied block. # ----------------------------------------------------------------------
def classify(event: Reading | Alarm | Heartbeat) -> str: match event: case Alarm(code=code, status=Status.FAILED): return f"trip on {code}" case Alarm(code=code, status=status): return f"alarm {code} is {status.value}" case Reading(sensor=sensor, value=value) if value > 100.0: return f"{sensor} over range at {value}" case Reading(sensor=sensor, value=value): return f"{sensor} reads {value}" case Heartbeat(node=node): return f"{node} is alive" case _: return "unrecognised event"
def route(command: list[str]) -> str: match command: case []: return "no command" case ["stop" | "halt"]: return "stopping" case ["arm", node]: return f"arming {node}" case ["set", key, value]: return f"{key} set to {value}" case ["log", *rest]: return f"log of {len(rest)} entries" case _: return "unsupported command"
def unpack(payload: dict[str, object]) -> str: match payload: case {"kind": "reading", "sensor": str(sensor), "value": float(value)}: return f"reading {sensor}={value}" case {"kind": "alarm", "code": code}: return f"alarm {code}" case {"kind": kind}: return f"unsupported kind {kind}" case _: return "no kind given"
